 * @returns `in YYYY` or `on Month D, YYYY`.
 */
function phrase(date: string): string {
	if (date.length === 4) return `in ${date}`;
	const [y, m, d] = date.split('-').map(Number);
	return `on ${MONTHS[m - 1]} ${d}, ${y}`;
}

/**
 * Phrases how long the person has been buried.
}

