() => {
  const src = {id:'s1',url:'https://www.findagrave.com/memorial/1/elias-whitmore',title:'Find a Grave — Elias Whitmore',site:'findagrave.com',snippet:''};
  const cand = {name:'Elias Whitmore',born:'1803',died:'1849',confidence:'high',sources:[src]};
  window.__hold = true;
  const real = window.fetch;
  window.fetch = async (url) => {
    const j = (b) => new Response(JSON.stringify(b),{headers:{'content-type':'application/json'}});
    if (url === '/api/read') return j({people:[{carvedName:'E. Whitmore',name:'E. Whitmore',maidenName:null,born:'1803',died:'1849'}]});
    if (url === '/api/research') { while (window.__hold) await new Promise(r=>setTimeout(r,100)); return j({candidates:[cand]}); }
    if (url === '/api/story') return j({status:'told',paragraph:'I was born in the spring of 1803, and the records remember little else of the first years. I worked the land, raised a family, and watched this place change. Like everyone here, I left my mark, and now you are here reading it.',sources:[src]});
    return real(url);
  };
  // Hand a real image to the input so the preview has something to show.
  return fetch('/invitation.webp').then(r=>r.blob()).then(b=>{
    const dt = new DataTransfer(); dt.items.add(new File([b],'stone.webp',{type:'image/webp'}));
    const input = document.querySelector('input[type=file]'); input.files = dt.files;
    input.dispatchEvent(new Event('change',{bubbles:true})); return 'ok';
  });
}

